  IF (NEW.c4 IS NULL AND NEW.c7 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c4 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k10 violated'; END IF;
  IF (NEW.c7 IS NULL AND NEW.c4 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c4 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c7 IS NULL AND c4 IS NOT NULL AND c0=NEW.c0 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k10 violated'; END IF;
  IF (NEW.c4 IS NULL AND NEW.c7 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c4 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c7 IS NULL AND c4 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k10 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k10 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k10();
CREATE UNIQUE INDEX k11_0 ON T(c1,c2) WHERE c2 IS NOT NULL;
CREATE UNIQUE INDEX k11_1 ON T(c1) WHERE c2 IS NULL;
CREATE FUNCTION chk_k11() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k11 violated'; END IF;
  IF (NEW.c2 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k11 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k11 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k11();
CREATE UNIQUE INDEX k12 ON T(c1,c4) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX k13 ON T(c2,c4);
CREATE UNIQUE INDEX k14 ON T(c2,c6);
CREATE UNIQUE INDEX k15_0 ON T(c0,c6) WHERE c6 IS NOT NULL;
CREATE UNIQUE INDEX k15_1 ON T(c0) WHERE c6 IS NULL;
CREATE FUNCTION chk_k15() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k15 violated'; END IF;
  IF (NEW.c6 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k15 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k15 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k15();
